'use strict';class GalleryTemplates{static PhotoGalleryItem({activePage:b,metadata:a,currentMediaLinkIndex:c,overlayData:d,uuid:e}){return`
        <div id="photoThumbnailContainer${a.id}" class="photo-thumbnail-container photo-thumbnail" style="width:${a.thumbnailSmallWidth}px;height:${a.thumbnailSmallHeight}px;padding-left:0;padding-right:0;">
            <a class="lightGalleryIndexAnchor" name="lightGalleryIndex${c}"></a>
            <img loading="lazy" tag="${encodeURI(a.thumbnailUrlSmall)}?v=${e}" src="${encodeURI(a.thumbnailUrlSmall)}?v=${e}" class="photo-thumbnail-image" id="image${a.id}" width="${a.thumbnailSmallWidth}" height="${a.thumbnailSmallHeight}" style="background-color:lightgray;">
            <input type="hidden" name="filename${a.id}" id="filename${a.id}" value="${a.fileName}">
            <input type="hidden" name="thumbnailCentered${a.id}" id="thumbnailCentered${a.id}" value="${encodeURI(a.thumbnailUrlCentered)}">
            
            ${"share"===b?`<div class="thumbnail-bl" id="tnbl${a.id}">
                <a href="/api/v1${a.type.includes("video")?"/video/":"/image/"}${a.id}/download" id="download${a.id}">
                    <span class="bi-download" style="font-size: 1rem;color: lightgray;"></span>
                </a>
            </div>`:""}
    
            ${d.hasOwnProperty("data")&&d.data.hasOwnProperty("overlayFlags")&&d.data.overlayFlags.hasOwnProperty("renderTopRight")&&!0===d.data.overlayFlags.renderTopRight?GalleryTemplates.getTopRightOverlay({id:a.id,overlays:d.overlays,data:d.data}):""}
            
            ${d.hasOwnProperty("data")&&d.data.hasOwnProperty("overlayFlags")&&d.data.overlayFlags.hasOwnProperty("renderTopLeft")&&!0===d.data.overlayFlags.renderTopLeft?GalleryTemplates.getTopLeftOverlay({id:a.id,overlays:d.overlays,data:d.data}):""}
            
            ${d.hasOwnProperty("data")&&d.data.hasOwnProperty("overlayFlags")&&d.data.overlayFlags.hasOwnProperty("renderBottomLeft")&&!0===d.data.overlayFlags.renderBottomLeft?GalleryTemplates.getBottomLeftOverlay({metadata:a,overlays:d.overlays,data:d.data}):""}
            
            ${d.hasOwnProperty("data")&&d.data.hasOwnProperty("overlayFlags")&&d.data.overlayFlags.hasOwnProperty("renderBottomRight")&&!0===d.data.overlayFlags.renderBottomRight?GalleryTemplates.getBottomRightOverlay({id:a.id,overlays:d.overlays,data:d.data}):""}
            
            ${d.hasOwnProperty("data")&&d.data.hasOwnProperty("overlayFlags")&&d.data.overlayFlags.hasOwnProperty("renderCenter")&&!0===d.data.overlayFlags.renderCenter?GalleryTemplates.getCenteredOverlay({id:a.id,overlays:d.overlays,data:d.data,uuid:e,activePage:b}):""}
            
        </div>
        ${"album"===b?`<span id="albummodal${a.id}" style="width:0;height:0;padding:0"></span>`:""}
        ${"person"===b?`<span id="personmodal${a.id}" style="width:0;height:0;padding:0"></span>`:""}
        
        <script type="text/javascript"${0<shashin.nonce.length?' nonce="'+shashin.nonce+'"':""}>
            shashin.setPhotoOverlays({id:"${a.id}",type:"${a.type}",lat:"${null===a.lat?"":`${a.lat}`}", lng:"${null===a.lng?"":`${a.lng}`}", year:${a.year}, month:${a.month}, day:${a.day}, fileName:"${a.fileName}", thumbnailUrlSmall:"${a.thumbnailUrlSmall}"}, "${b}");
            Util.activateMetadataListeners("${a.id}");
            $("#mediaLink${a.id}").attr("tag", "${a.id}");
            
            ${!1===d.hasOwnProperty("data")||!1===d.data.hasOwnProperty("overlayFlags")||!1===d.data.overlayFlags.hasOwnProperty("renderBottomLeft")||!1===d.data.overlayFlags.renderBottomLeft||-1!==$.inArray("isInfo",d.overlays)?`
                $("#infoModalEdit${a.id}").on("click", function (e) {
                    e.preventDefault();
                    shashin.openEditMetadataModal("${a.id}");
                })
                `:`
                $("#metadataModalEdit${a.id}").on("click", function (e) {
                    e.preventDefault();
                    shashin.openEditMetadataModal("${a.id}");
                })
                `}
    
            $("#image${a.id}").on('load', function () {
                $(this).css("background-color", "transparent");
            });
            
            // Util.checkErrorImage();
        </script>        
    `}static getTopRightOverlay({id:b,overlays:a,data:c}){return`
        <div class="thumbnail-tr" id="tntr${b}">

        ${-1!==$.inArray("isVideo",a)?`
            <span class="overlayIconBackground"><span id="duration${b}">${c.duration}</span>
                <span id="video${b}" class="bi-camera-video overlayIcon" title="video"></span>
            </span>
            <br>
            `:""} 
        
        ${-1!==$.inArray("isPan",a)?`
            <span id="panorama${b}" class="bi-aspect-ratio overlayIcon overlayIconBackground" title="panorama"></span>
            <br>
            `:""}
        
        ${-1!==$.inArray("isGif",a)?`
            <span id="gif${b}" class="bi-layers overlayIcon overlayIconBackground" title="gif"></span>
            <br>
            `:""}
        
        ${-1!==$.inArray("isTagged",a)?'\n            <span class="bi-bookmark-fill overlayIconBackground" style="font-size: 1rem;color: lightsalmon;"></span>\n            ':""}
    
        </div>
    `}static getTopLeftOverlay({id:b}){return`
        <div class="thumbnail-tl" id="tntl${b}">
            <a href="#" id="select${b}">
                <span id="tlicon${b}" class="bi-circle" style="font-size: 1rem;color: lightgray;"></span>
            </a>
        </div>
    `}static getBottomRightOverlay({id:b,overlays:a,data:c}){return`
        <div class="thumbnail-br" id="tnbr${b}">
            ${-1!==$.inArray("isComments",a)?`
            
            <a href="#" data-bs-toggle="modal" data-bs-target="#propalbumphotocomment${b}" class="overlayCommentIconBackground overlayCommentText">
                <span id="brcommentcount${b}">${c.albumPhotoCommentsMap.hasOwnProperty(b)?c.albumPhotoCommentsMap[b].length:"0"}</span> 
                <span id="bricon${b}" class="bi-chat-square position-relative overlayCommentIcon">
                </span>
            </a>
            `:""}
            ${-1!==$.inArray("isFavorites",a)?`
            <br>
            <a href="#" id="favorite${b}" class="text-decoration-none">
                <span class="overlayIconBackground">
                    <span id="briconcount${b}">${c.favoriteCount}</span>&nbsp;<span class="${c.favoriteIcon} overlayIcon" id="brfavoriteicon${b}"></span>
                </span>
            </a>
            `:""}
        </div>
    `}static getBottomLeftOverlay({metadata:b,overlays:a,data:c}){return`
        <div class="thumbnail-bl" id="tnbl${b.id}">
            ${-1!==$.inArray("isBlOnClickFunction",a)?`
            <br>
            <a href="#" id="${c.onClickIdPrefix}${b.id}">
                <span class="bi-journal-album" style="font-size: 1rem;color: lightgray;" title="Set as album cover"></span>
            </a>
    
            <script type="text/javascript"${0<shashin.nonce.length?' nonce="'+shashin.nonce+'"':""}>
                $("#${c.onClickIdPrefix}${b.id}").on("click", function (e) {
                    e.preventDefault();
                    ${c.blOnClickFunction}(e,"${b.id}");
                });
            </script>
            `:""}
            
            ${-1!==$.inArray("isOnClickIdPrefix",a)?`
            <br>
            <a href="#" data-bs-toggle="modal" data-bs-target="#${c.onClickIdPrefix}${b.id}">
                <span class="bi-pencil" style="font-size: 1rem;color: lightgray;"></span>
            </a>
            `:""}
            
            ${-1!==$.inArray("isInfo",a)?`
            <br>
            <a href="#" id="infoModalEdit${b.id}" tag="${b.id}">
                <span class="${null!==b.lat&&null!==b.lng?"bi-info-circle":"bi-info-square"}" style="font-size: 1rem;color: lightgray;" title="Set as album cover"></span>
            </a>
            `:""}
            
            ${-1!==$.inArray("isEditControls",a)?`
            <a href="#" id="metadataModalEdit${b.id}" data-bs-target="#propTimelinModal" tag="${b.id}">
                <span class="${c.editIcon}" style="font-size: 1rem;color: lightgray;"></span>
            </a>
            `:""}
        </div>
    `}static getCenteredOverlay({id:b,overlays:a,data:c,uuid:d,activePage:e}){return`
        <div class="thumbnail-centered" id="tncentered${b}">
    
            ${-1!==$.inArray("isVideo",a)?`
                <a class="mediaLink" id="mediaLink${b}" data-download-url="${encodeURI(c.metadata.videoUrl)}/download" 
                    ${null!==c.metadata.description?` data-sub-html="${c.metadata.description}" `:""}
                    data-metadata-id="${c.metadata.id}"
                    data-poster="${null===c.metadata.thumbnailUrlOriginal||""===c.metadata.thumbnailUrlOriginal?c.metadata.thumbnailUrlSmall:encodeURI(c.metadata.thumbnailUrlOriginal)}?v=${d}"
                    data-lg-size="${null===c.metadata.originalImageWidth||""===c.metadata.originalImageWidth?`${c.metadata.thumbnailSmallWidth}-${c.metadata.thumbnailSmallHeight}`:`${c.metadata.originalImageWidth}-${c.metadata.originalImageHeight}`}"
                    data-video=\'{"source": [{"src":"${c.metadata.videoUrl}", "type":"video/mp4"}], "attributes": {"preload": false, "controls": true, "autoplay": true}}\'>
                    ${"slideshow"!==e?'<span class="bi-play-circle" style="font-size: 4rem;color: lightgray;"></span>':""}
                </a>
                `:`
                <a class="mediaLink" id="mediaLink${b}" data-src="${c.metadata.thumbnailUrlOriginal}" href="${c.metadata.thumbnailUrlOriginal}"
                    data-download-url="${encodeURI(c.metadata.thumbnailUrlOriginal)}/download"
                    data-metadata-id="${c.metadata.id}"
                    ${null!==c.metadata.description?` data-sub-html="${c.metadata.description}" `:""}>
                    ${"slideshow"!==e?'<span class="bi-play-circle" style="font-size: 4rem;color: lightgray;"></span>':""}
                </a>
                `}
    
            <script type="text/javascript"${0<shashin.nonce.length?` nonce="${shashin.nonce}"`:""}>
                $("#mediaLink${b}").on("click", function (e) {
                    e.preventDefault();
                    ${c.cOnClickFunction}(e,${c.galleryIndex});
                });
            </script>
    
        </div>
    `}static getFoldersCard({folder:b,thumbnailUrlCentered:a,count:c,appendClass:d}){return`
        <div class="card" style="width:235px;padding-top:10px;">
            <a href="/folder/${encodeURIComponent(encodeURIComponent(b))}" style="text-decoration: none !important;color: #777777;">
                <img loading="lazy" class="card-img-top" src="${a}" width="209" height="209" style="width: 209px;height: 209px;">
            </a>
            <div class="card-body">
                <p class="card-text"><strong>${b}</strong></p>
                <p class="card-text"><small class="text-muted">${c} items</small></p>
            </div>
        </div>
        
        <span class="${d}" style="width:0;height:0;padding:0"></span>
    `}}
;
